def refuse(msg):
    raise SystemExit('RA28 REFUSED: %s' % msg)


def load(rel):
    with open(os.path.join(ROOT, rel), 'rb') as f:
        raw = f.read()
    return raw.decode('utf-8-sig'), raw[:3] == b'\xef\xbb\xbf'


def main():
    check = '--check' in sys.argv[1:]
    ps1, _ = load('Push-PendingChanges.ps1')
    if "'test_ra28_filters_and_outside_rules.py'" in ps1:
        print('RA28 already applied.')
        return 0
    if "'test_ra27_rules_preview_plots_pc_progress.py'" not in ps1:
        refuse('RA27 (apply_ra27_rules_preview_plots_pc_progress.py) is not applied - '
               'this round registers after it.')
    for rel in SHIPPED:
        if not os.path.isfile(os.path.join(ROOT, *rel.split('/'))):
            refuse('%s is not in place - it ships with this patcher; copy it '
                   'in first.' % rel)
    # A file's edits are made one after another on the same text, in the
    # order listed; every anchor must be found exactly once when its turn
    # comes, or nothing at all is written.
    texts, order = {}, []
    for rel, old, new in EDITS:
        if rel not in texts:
            texts[rel] = list(load(rel))
            order.append(rel)
        text = texts[rel][0]
        if text.count(old) != 1:
            refuse('%s: the anchor is found %d time(s), not once'
                   % (rel, text.count(old)))
        texts[rel][0] = text.replace(old, new)
    plan = [(rel, texts[rel][0], texts[rel][1]) for rel in order]
    for rel, text, bom in plan:
        if check:
            print('RA28 --check: %s would change' % rel)
            continue
        p = os.path.join(ROOT, rel)
        if not os.path.exists(p + SUFFIX):
            shutil.copy2(p, p + SUFFIX)
        with open(p, 'wb') as f:
            f.write((b'\xef\xbb\xbf' if bom else b'') + text.encode('utf-8'))
        print('  changed %s' % rel)
    for rel in RETIRED:
        p = os.path.join(ROOT, *rel.split('/'))
        if not os.path.isfile(p):
            continue
        if check:
            print('RA28 --check: %s would be moved to %s' % (rel, SUFFIX))
            continue
        if os.path.exists(p + SUFFIX):
            os.remove(p)
        else:
            os.rename(p, p + SUFFIX)
        print('  retired %s (kept as %s)' % (rel, SUFFIX))
    if not check:
        print('RA28 applied - filters, outside your rules, comments in the rows, opened. Now: python manage.py migrate')
    return 0


if __name__ == '__main__':
    sys.exit(main())
